CREATE INDEX IF NOT EXISTS idx_projects_client ON projects(client_id); CREATE INDEX IF NOT EXISTS idx_documents_project ON documents(project_id); CREATE INDEX IF NOT EXISTS idx_expenses_project ON expenses(project_id); CREATE INDEX IF NOT EXISTS idx_events_project ON project_events(project_id,created_at DESC);
